const defaultConnectionSettings = {
    host: 'api.stripe.com',
    port: 443,
};
/** @internal */
// eslint-disable-next-line import/no-mutable-exports
export let connectionSettings = defaultConnectionSettings;
/** @internal */
export const setConnectionSettings = (settings) => {
    connectionSettings = {
        ...defaultConnectionSettings,
        ...settings,
    };
};
